-- =====================================================================
-- TrAIn · Esquema PostgreSQL (v0.3, 2026-10-25) · 14 tablas
-- Capas 1-3. La capa 4 (simulación + etiquetas) vive en Parquet, fuera de la BD.
-- Unidades: kg, cm, minutos/segundos.
-- Los ids usan GENERATED BY DEFAULT AS IDENTITY: la app deja que PostgreSQL
-- los genere y el simulador puede insertar los suyos (luego se reajustan
-- las secuencias con sql/reajustar_secuencias.sql).
-- =====================================================================

BEGIN;

-- ---------------------------------------------------------------------
-- CAPA 1 · CATÁLOGO
-- ---------------------------------------------------------------------

CREATE TABLE grupo_muscular (
    id      SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre  TEXT NOT NULL UNIQUE
);

CREATE TABLE musculo (
    id        SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre    TEXT NOT NULL UNIQUE,
    grupo_id  SMALLINT NOT NULL REFERENCES grupo_muscular(id)
);

CREATE TABLE patron_movimiento (
    id      SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre  TEXT NOT NULL UNIQUE
);

CREATE TABLE ejercicio (
    id               SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_es        TEXT NOT NULL UNIQUE,
    nombre_en        TEXT,
    grupo_id         SMALLINT NOT NULL REFERENCES grupo_muscular(id),
    patron_id        SMALLINT NOT NULL REFERENCES patron_movimiento(id),
    mecanica         TEXT NOT NULL CHECK (mecanica IN ('compuesto','aislamiento')),
    equipamiento     TEXT NOT NULL CHECK (equipamiento IN
                       ('barra','mancuerna','polea','maquina_placas','maquina_guiada',
                        'smith','peso_corporal','kettlebell','otro')),
    tipo_carga       TEXT NOT NULL CHECK (tipo_carga IN
                       ('externa','corporal','corporal_lastre','asistida','tiempo','transporte')),
    lateralidad      TEXT NOT NULL CHECK (lateralidad IN ('bilateral','unilateral')),
    incremento_kg    NUMERIC(4,2) NOT NULL DEFAULT 2.5 CHECK (incremento_kg >= 0),
    reps_min         SMALLINT CHECK (reps_min > 0),
    reps_max         SMALLINT CHECK (reps_max >= reps_min),
    factor_fatiga    REAL NOT NULL DEFAULT 0.5 CHECK (factor_fatiga BETWEEN 0 AND 1),
    ratio_fuerza_ref REAL,          -- solo simulador: e1RM típico / peso corporal
    es_nucleo        BOOLEAN NOT NULL DEFAULT TRUE,
    en_modelo_carga  BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE ejercicio_musculo (
    ejercicio_id  SMALLINT NOT NULL REFERENCES ejercicio(id),
    musculo_id    SMALLINT NOT NULL REFERENCES musculo(id),
    rol           TEXT NOT NULL CHECK (rol IN ('primario','secundario')),
    factor        REAL NOT NULL CHECK (factor > 0 AND factor <= 1),
    PRIMARY KEY (ejercicio_id, musculo_id)
);

-- ---------------------------------------------------------------------
-- CAPA 2 · REGISTRO
-- ---------------------------------------------------------------------

CREATE TABLE usuario (
    id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sexo             TEXT CHECK (sexo IN ('H','M','otro')),
    fecha_nacimiento DATE,
    altura_cm        REAL CHECK (altura_cm BETWEEN 100 AND 250),
    nivel            TEXT NOT NULL CHECK (nivel IN ('principiante','intermedio','avanzado')),
    objetivo         TEXT NOT NULL CHECK (objetivo IN
                       ('fuerza','hipertrofia','mantenimiento','perdida_grasa')),
    dias_semana      SMALLINT CHECK (dias_semana BETWEEN 1 AND 7),
    fecha_alta       DATE NOT NULL,
    es_sintetico     BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE medida_corporal (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id  INTEGER NOT NULL REFERENCES usuario(id) ON DELETE CASCADE,
    fecha       DATE NOT NULL,
    peso_kg     REAL NOT NULL CHECK (peso_kg BETWEEN 30 AND 300),
    grasa_pct   REAL CHECK (grasa_pct BETWEEN 2 AND 70),
    UNIQUE (usuario_id, fecha)
);

CREATE TABLE programa (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id     INTEGER NOT NULL REFERENCES usuario(id) ON DELETE CASCADE,
    tipo_division  TEXT NOT NULL CHECK (tipo_division IN
                     ('full_body','torso_pierna','ppl','weider','otro')),
    fecha_inicio   DATE NOT NULL,
    fecha_fin      DATE,
    activo         BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE programa_ejercicio (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    programa_id   BIGINT NOT NULL REFERENCES programa(id) ON DELETE CASCADE,
    dia           SMALLINT NOT NULL CHECK (dia BETWEEN 1 AND 7),  -- día de la rutina
    orden         SMALLINT NOT NULL,
    ejercicio_id  SMALLINT NOT NULL REFERENCES ejercicio(id),
    series_obj    SMALLINT NOT NULL CHECK (series_obj > 0),
    reps_obj      SMALLINT CHECK (reps_obj > 0),
    rpe_obj       NUMERIC(3,1) CHECK (rpe_obj BETWEEN 5 AND 10),
    UNIQUE (programa_id, dia, orden)
);

CREATE TABLE sesion (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id      INTEGER NOT NULL REFERENCES usuario(id) ON DELETE CASCADE,
    programa_id     BIGINT REFERENCES programa(id),
    dia_programa    SMALLINT,
    fecha           DATE NOT NULL,
    hora_inicio     TIME,
    duracion_min    SMALLINT CHECK (duracion_min >= 0),
    -- Cuestionario opcional (NULL = no respondido). Antes de entrenar:
    sueno           SMALLINT CHECK (sueno BETWEEN 1 AND 3),            -- mal/normal/bien
    cuerpo          SMALLINT CHECK (cuerpo BETWEEN 1 AND 3),           -- fresco/algo cargado/muy cargado
    energia         SMALLINT CHECK (energia BETWEEN 1 AND 3),          -- baja/normal/alta
    actividad_extra SMALLINT CHECK (actividad_extra BETWEEN 0 AND 2),  -- no/suave/intenso
    dolor           BOOLEAN,
    zona_dolor_id   SMALLINT REFERENCES grupo_muscular(id),
    -- Después de entrenar:
    dureza_sesion   SMALLINT CHECK (dureza_sesion BETWEEN 1 AND 4),    -- fácil/moderada/dura/al límite
    notas           TEXT,
    CHECK (zona_dolor_id IS NULL OR dolor)
);

CREATE TABLE serie (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sesion_id        BIGINT NOT NULL REFERENCES sesion(id) ON DELETE CASCADE,
    ejercicio_id     SMALLINT NOT NULL REFERENCES ejercicio(id),
    orden_ejercicio  SMALLINT NOT NULL,
    num_serie        SMALLINT NOT NULL,
    tipo             TEXT NOT NULL DEFAULT 'efectiva' CHECK (tipo IN
                       ('calentamiento','efectiva','descendente','fallo')),
    reps_obj         SMALLINT,
    reps             SMALLINT CHECK (reps >= 0),
    carga_kg         REAL CHECK (carga_kg >= 0),      -- por lado si es unilateral
    lastre_kg        REAL CHECK (lastre_kg >= 0),
    asistencia_kg    REAL CHECK (asistencia_kg >= 0),
    duracion_s       SMALLINT CHECK (duracion_s >= 0),
    distancia_m      REAL CHECK (distancia_m >= 0),
    rpe              NUMERIC(3,1) CHECK (rpe BETWEEN 1 AND 10),  -- app: 6 a 10, pasos de 0,5
    completada       BOOLEAN NOT NULL DEFAULT TRUE,
    UNIQUE (sesion_id, orden_ejercicio, num_serie)
);

-- ---------------------------------------------------------------------
-- CAPA 3 · DERIVADOS Y ML
-- ---------------------------------------------------------------------

CREATE TABLE rendimiento_ejercicio (
    usuario_id          INTEGER NOT NULL REFERENCES usuario(id) ON DELETE CASCADE,
    sesion_id           BIGINT NOT NULL REFERENCES sesion(id) ON DELETE CASCADE,
    ejercicio_id        SMALLINT NOT NULL REFERENCES ejercicio(id),
    fecha               DATE NOT NULL,
    carga_efectiva_top  REAL,
    reps_top            SMALLINT,
    rpe_top             REAL,
    e1rm                REAL,
    volumen_kg          REAL,
    series_efectivas    SMALLINT,
    reps_fallidas       SMALLINT,
    PRIMARY KEY (sesion_id, ejercicio_id)
);

CREATE TABLE estado_diario (
    usuario_id             INTEGER NOT NULL REFERENCES usuario(id) ON DELETE CASCADE,
    fecha                  DATE NOT NULL,
    carga_sesion           REAL,     -- sRPE x minutos del día (0 si no entrena)
    carga_aguda_7d         REAL,
    carga_cronica_28d      REAL,     -- media semanal de las últimas 4 semanas
    acwr                   REAL,
    volumen_por_musculo    JSONB,    -- {musculo: series ponderadas en 7 días}
    dias_desde_ultima      SMALLINT,
    sesiones_consecutivas  SMALLINT,
    PRIMARY KEY (usuario_id, fecha)
);

CREATE TABLE recomendacion (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id      INTEGER NOT NULL REFERENCES usuario(id) ON DELETE CASCADE,
    fecha           DATE NOT NULL,
    tipo            TEXT NOT NULL CHECK (tipo IN ('carga','estado','fatiga')),
    ejercicio_id    SMALLINT REFERENCES ejercicio(id),
    valor_num       REAL,
    clase           TEXT CHECK (clase IN ('entrenar','suave','descansar')),
    modelo_version  TEXT NOT NULL,
    generado_en     TIMESTAMPTZ NOT NULL DEFAULT now(),
    aceptada        BOOLEAN,
    valor_real      REAL,
    CHECK (tipo <> 'carga' OR ejercicio_id IS NOT NULL)
);

-- ---------------------------------------------------------------------
-- ÍNDICES
-- ---------------------------------------------------------------------
CREATE INDEX ix_sesion_usuario_fecha  ON sesion (usuario_id, fecha);
CREATE INDEX ix_serie_sesion          ON serie (sesion_id);
CREATE INDEX ix_rend_usuario_ej_fecha ON rendimiento_ejercicio (usuario_id, ejercicio_id, fecha);
CREATE INDEX ix_medida_usuario_fecha  ON medida_corporal (usuario_id, fecha);
CREATE INDEX ix_recom_usuario_fecha   ON recomendacion (usuario_id, fecha, tipo);
CREATE INDEX ix_programa_usuario      ON programa (usuario_id);

COMMIT;
